## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------------
  localparam int CLK_PERIOD = 8;   // 125 MHz clock

  // ------------------------------------------------------------------
  // DUT interface signals
  // ------------------------------------------------------------------
  logic               clk;
  logic               rst;
  logic [15:0]        prescale;
  logic [7:0]         s_axis_tdata;
  logic               s_axis_tvalid;
  logic               s_axis_tready;
  logic               txd;
  logic               busy;

  // ------------------------------------------------------------------
  // Instantiate the AXI‑Stream UART transmitter (default parameters)
  // ------------------------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd          (txd),
    .busy         (busy),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------------
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------------
  // Reset sequence
  // ------------------------------------------------------------------
  initial begin
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // ------------------------------------------------------------------
  // Keep prescale at the minimum value (1) for the whole run
  // ------------------------------------------------------------------
  initial prescale = 16'd1;

  // ------------------------------------------------------------------
  // Task: send one byte over the AXI‑Stream interface
  // ------------------------------------------------------------------
  task automatic axis_send_byte(input byte unsigned data);
    // Wait until the slave signals that it is ready
    wait (s_axis_tready);
    // Present the data and assert tvalid on the next rising edge
    @(posedge clk);
    s_axis_tdata  <= data;
    s_axis_tvalid <= 1'b1;
    // De‑assert tvalid one cycle later (handshake completes)
    @(posedge clk);
    s_axis_tvalid <= 1'b0;
  endtask

  // ------------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------------
  initial begin
    // Give the design a couple of clocks after reset release
    repeat (4) @(posedge clk);

    // Ensure the transmitter is idle before the first transfer
    wait (!busy && s_axis_tready);

    // ----- First word : 0x96 ------------------------------------------------
    axis_send_byte(8'h96);
    // Wait until the transmitter finishes this word
    wait (!busy);
    // Make sure we are back to idle
    wait (!busy && s_axis_tready);

    // ----- Second word : 0x69 (back‑to‑back) ---------------------------------
    axis_send_byte(8'h69);
    // Allow enough cycles for the coverage property to evaluate
    repeat (12) @(posedge clk);

    $finish;   // End simulation cleanly
  end

endmodule
```

